import math
from datetime import datetime, timedelta

FREE_DURATION = timedelta(minutes=15)
PENALTY_DURATION = timedelta(hours=24)
PENALTY_FEE = 200.00


class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = hourly_rate

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time.")

        duration = exit - entry

        if duration > PENALTY_DURATION:
            return PENALTY_FEE

        if duration <= FREE_DURATION:
            return 0.0

        hours = math.ceil(duration / timedelta(hours=1))
        return round(hours * self.hourly_rate, 2)
